CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// One block per (n, g) pair.
// Phase 1: compute mean and variance over (C/G * H * W) elements.
// Phase 2: normalize, apply affine+scale, then perform maxpool and clamp,
//          writing only the downsampled output.

__global__ void fused_gn_scale_pool_clamp_kernel(
    const float* __restrict__ input,   // [N, C, H, W]
    const float* __restrict__ gn_w,    // [C]
    const float* __restrict__ gn_b,    // [C]
    const float* __restrict__ scale,   // [C] (broadcast from [C,1,1])
    float* __restrict__ output,        // [N, C, pH, pW]
    int N, int C, int H, int W,
    int num_groups, float eps,
    int pool_k,
    int pH, int pW,
    float clamp_min, float clamp_max
) {
    // blockIdx.x = n, blockIdx.y = g
    const int n = blockIdx.x;
    const int g = blockIdx.y;
    const int cpg = C / num_groups;  // channels per group
    const int c_start = g * cpg;
    const int spatial = H * W;
    const int group_elems = cpg * spatial;

    extern __shared__ float smem[];
    // smem layout: [blockDim.x] for partial sums, [blockDim.x] for partial sum-of-squares
    float* s_sum  = smem;
    float* s_sum2 = smem + blockDim.x;

    // --- Phase 1: compute mean and variance ---
    float local_sum  = 0.0f;
    float local_sum2 = 0.0f;
    for (int i = threadIdx.x; i < group_elems; i += blockDim.x) {
        int c = c_start + i / spatial;
        int hw = i % spatial;
        float v = input[((n * C + c) * H + hw / W) * W + hw % W];
        local_sum  += v;
        local_sum2 += v * v;
    }
    s_sum[threadIdx.x]  = local_sum;
    s_sum2[threadIdx.x] = local_sum2;
    __syncthreads();

    // block reduction
    for (int stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x]  += s_sum[threadIdx.x + stride];
            s_sum2[threadIdx.x] += s_sum2[threadIdx.x + stride];
        }
        __syncthreads();
    }
    float mean = s_sum[0]  / (float)group_elems;
    float var  = s_sum2[0] / (float)group_elems - mean * mean;
    float inv_std = rsqrtf(var + eps);

    // --- Phase 2: normalize + affine + scale + maxpool + clamp ---
    // Each thread handles one or more pooled output pixels for all channels in group.
    // pooled output: pH * pW pixels per channel
    const int pooled_pixels = pH * pW;
    for (int c_off = 0; c_off < cpg; c_off++) {
        int c = c_start + c_off;
        float w = gn_w[c];
        float b = gn_b[c];
        float sc = scale[c];
        float affine_scale = w * inv_std * sc;
        float affine_bias  = b - w * mean * inv_std * sc;  // fused bias after scale
        // Wait: bias from groupnorm before scale: (val*w + b) * sc = val*w*sc + b*sc
        // So affine_scale = w * inv_std * sc, affine_bias = (b - w*mean*inv_std) * sc
        // Recompute correctly:
        float gn_bias_term = b - w * mean * inv_std;
        affine_bias = gn_bias_term * sc;

        for (int p = threadIdx.x; p < pooled_pixels; p += blockDim.x) {
            int ph = p / pW;
            int pw = p % pW;
            // pool window: [ph*pool_k, (ph+1)*pool_k) x [pw*pool_k, (pw+1)*pool_k)
            float max_val = -FLT_MAX;
            for (int kh = 0; kh < pool_k; kh++) {
                int h_in = ph * pool_k + kh;
                if (h_in >= H) continue;
                for (int kw = 0; kw < pool_k; kw++) {
                    int w_in = pw * pool_k + kw;
                    if (w_in >= W) continue;
                    float raw = input[((n * C + c) * H + h_in) * W + w_in];
                    float normed = raw * affine_scale + affine_bias;
                    if (normed > max_val) max_val = normed;
                }
            }
            // clamp
            max_val = fmaxf(clamp_min, fminf(clamp_max, max_val));
            output[((n * C + c) * pH + ph) * pW + pw] = max_val;
        }
    }
}

torch::Tensor fused_post_ops(
    torch::Tensor x,
    torch::Tensor gn_weight,
    torch::Tensor gn_bias,
    torch::Tensor scale,
    int64_t num_groups,
    double eps,
    int64_t pool_k,
    double clamp_min,
    double clamp_max
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    x = x.to(torch::kFloat32);

    const int N = x.size(0);
    const int C = x.size(1);
    const int H = x.size(2);
    const int W = x.size(3);
    const int pH = H / (int)pool_k;
    const int pW = W / (int)pool_k;

    auto gn_w = gn_weight.contiguous().to(torch::kFloat32);
    auto gn_b = gn_bias.contiguous().to(torch::kFloat32);
    // scale shape is [C, 1, 1] -> flatten to [C]
    auto sc = scale.contiguous().to(torch::kFloat32).view({C});

    auto output = torch::empty({N, C, pH, pW}, x.options());

    const int threads = 256;
    dim3 grid(N, num_groups);
    size_t smem_bytes = 2 * threads * sizeof(float);

    fused_gn_scale_pool_clamp_kernel<<<grid, threads, smem_bytes>>>(
        x.data_ptr<float>(),
        gn_w.data_ptr<float>(),
        gn_b.data_ptr<float>(),
        sc.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W,
        (int)num_groups, (float)eps,
        (int)pool_k,
        pH, pW,
        (float)clamp_min, (float)clamp_max
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs convolution, group normalization, scaling, max pooling, and clamping.
        """
    def __init__(self, in_channels, out_channels, kernel_size, num_groups, scale_shape, maxpool_kernel_size, clamp_min, clamp_max):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.group_norm = nn.GroupNorm(num_groups, out_channels)
        self.scale = nn.Parameter(torch.ones(scale_shape))
        self.maxpool = nn.MaxPool2d(kernel_size=maxpool_kernel_size)
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Args:
                    x: Input tensor of shape (batch_size, in_channels, height, width).
                Returns:
                    Output tensor of shape (batch_size, out_channels, height', width').
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.conv(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        pool_k = self.maxpool.kernel_size
        if isinstance(pool_k, (tuple, list)):
            pool_k = pool_k[0]
        x = _stark_get_extension().fused_post_ops(
            x,
            self.group_norm.weight,
            self.group_norm.bias,
            self.scale,
            self.group_norm.num_groups,
            self.group_norm.eps,
            int(pool_k),
            float(self.clamp_min),
            float(self.clamp_max),
        )
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        # scale multiply fused into fused_post_ops
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        # maxpool fused into fused_post_ops
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        # clamp fused into fused_post_ops
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_7>>>
        return x
        # <<<END_IMPROVE>>>

