// ---------------------------------------------------------------------------
// Specialized kernel: channels_per_group == 4, pool_k == 2.
// One block per (n, g).  Warp-shuffle reduction replaces shared-memory tree.
// Phase-1 iterates over spatial positions with4 precomputed channel base
// offsets, eliminating the div/mod address arithmetic from the original loop.
// Launch with 128 threads (4warps); smem used only for inter-warp merge.
// ---------------------------------------------------------------------------
__global__ void fused_gn_scale_pool_clamp_k4_p2(
    const float* __restrict__ input,
    const float* __restrict__ gn_w,
    const float* __restrict__ gn_b,
    const float* __restrict__ scale,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int num_groups, float eps,
    int pH, int pW,
    float clamp_min, float clamp_max
