    const int n       = blockIdx.x;
    const int g       = blockIdx.y;
    const int c_start = g * 4;// cpg == 4
    const int spatial = H * W;// elements per channel
    const int group_elems = 4 * spatial;

    // --- Phase1: spatial loop over hw, load all 4 channels per position ---
    // Precompute flat base offsets for each of the 4 channels to avoid
    // repeated (i / spatial) and (i % spatial) integer divisions.
    const int base0 = (n * C + c_start + 0) * spatial;
    const int base1 = (n * C + c_start + 1) * spatial;
    const int base2 = (n * C + c_start + 2) * spatial;
    const int base3 = (n * C + c_start + 3) * spatial;

    float local_sum  = 0.0f;
    float local_sum2 = 0.0f;
    for (int hw = threadIdx.x; hw < spatial; hw += blockDim.x) {
        float v0 = input[base0 + hw];
        float v1 = input[base1 + hw];
        float v2 = input[base2 + hw];
        float v3 = input[base3 + hw];
        local_sum  += v0 + v1 + v2 + v3;
        local_sum2 += v0*v0 + v1*v1 + v2*v2 + v3*v3;
    }

    // intra-warp reduction
    #pragma unroll
    for (int mask = 16; mask > 0; mask >>= 1) {
        local_sum  += __shfl_xor_sync(0xffffffff, local_sum,  mask);
        local_sum2 += __shfl_xor_sync(0xffffffff, local_sum2, mask);
    }

    // inter-warp reduction via shared memory (4 warps max for 128 threads)
    __shared__ float warp_sum[4];
    __shared__ float warp_sum2[4];
    int warp_id = threadIdx.x >> 5;
    int lane= threadIdx.x & 31;
    if (lane == 0) {
        warp_sum[warp_id]  = local_sum;
        warp_sum2[warp_id] = local_sum2;
    }
    __syncthreads();

    // thread 0 accumulates across warps
    float total_sum  = 0.0f;
    float total_sum2 = 0.0f;
    if (threadIdx.x == 0) {
        int nwarps = (blockDim.x + 31) >> 5;
        for (int w = 0; w < nwarps; w++) {
            total_sum  += warp_sum[w];
            total_sum2 += warp_sum2[w];
        }
        warp_sum[0]  = total_sum;
        warp_sum2[0] = total_sum2;
    }
    __syncthreads();
float mean    = warp_sum[0]  / (float)group_elems;
    float var     = warp_sum2[0] / (float)group_elems - mean * mean;
    float inv_std = rsqrtf(var + eps);

