                    if (w_in >= W) continue;
                    float raw    = input[((n * C + c) * H + h_in) * W + w_in];
                    float normed = raw * asc[c_off] + abl[c_off];
                    if (normed > max_val) max_val = normed;
                }
            }
            max_val = fmaxf(clamp_min, fminf(clamp_max, max_val));
            output[((n * C + c) * pH + ph) * pW + pw] = max_val;
        }
    }
}

