// using float4 vectorized loads + warp shuffle, writes 2 floats per (n,g).
// stats layout: stats[n * num_groups * 2 + g * 2 + 0] = mean
//               stats[n * num_groups * 2 + g * 2 + 1] = inv_std
// ---------------------------------------------------------------------------
__launch_bounds__(128, 8)
__global__ void compute_group_stats_k4(
    const float* __restrict__ input,
    float* __restrict__ stats,
    int N, int C, int H, int W,
    int num_groups, float eps
