__launch_bounds__(128, 8)
__global__ void apply_gn_scale_pool_clamp_k4_tiled(
    const float* __restrict__ input,
    const float* __restrict__ gn_w,
    const float* __restrict__ gn_b,
    const float* __restrict__ scale,
